CREATE TYPE "public"."role" AS ENUM('sales_rep', 'sales_manager', 'finance', 'admin');--> statement-breakpoint
CREATE TYPE "public"."subject_kind" AS ENUM('staff', 'customer');--> statement-breakpoint
